INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('004e96df-b9b7-486f-8092-3c0fa3833201', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Database Creator', 'Create a database called shopdb. Run: mysql -u root -e "SHOW DATABASES" | grep shopdb. What is the output?', 50, '$2b$10$93b3DGyJdfIclBpJVdclbOYbwosjGsIQiGzCuEVHwM7TTCz8Rbkg2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5ff34333-0230-4796-8845-b02ffaa90420', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Table Architect', 'Create table products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50), price DECIMAL(10,2), stock INT DEFAULT 0). Run: DESCRIBE products | wc -l. How many columns (minus 1 for header)?', 75, '$2b$10$vcN08ELULqxqHtG044HeHuSAsGYDVd3gtrnYd0LbVamf8FDsOAV2e');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0f7e2dc1-efed-4a6a-9d82-7b507c624cfd', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$rhWAQXZ3T2LdfzZNEKi./ehb9l1XCeXiZDu4JZItCILljr00bH4Nu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fa57818c-f57a-4625-958c-6e9a307f0c00', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product name?', 75, '$2b$10$rH.Vl61dLMY4d/kDvOHENe0A8drrBgNyb2ONd75mDHKpgii30T9du');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7094d617-5fb4-443f-b468-f4142dcc25fd', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Index Builder', 'Create index on products(name). Run: SHOW INDEX FROM products WHERE Key_name != "PRIMARY" | wc -l. How many non-primary indexes?', 100, '$2b$10$xSd4mYUqs7yLMzfWXpVMqO7abI2LrkVCO0EMuQ3P3cbKLGQfewGVq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('304cf7d7-6829-4b03-8b79-b2194ea0dcfe', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'User Manager', 'Create user "appuser"@"localhost" identified by "secret123". Grant SELECT,INSERT on shopdb.*. Run: SHOW GRANTS FOR "appuser"@"localhost" | grep "ON shopdb.*". What privileges are shown?', 100, '$2b$10$w4CIBGWVXtiu0Bxy3kCPCOkxVZehmTpPz0D2O6BpLoNlBd9S0JweS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e549754c-e52e-45e9-8ea8-75120fa3066f', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Backup Creator', 'Run: mysqldump -u root shopdb > /tmp/backup.sql && wc -l /tmp/backup.sql. How many lines in the backup file?', 100, '$2b$10$3LSb8LGqyvO1fwCRatRPuOQ1.lPR785pMNiAYEQL7Vuy0nS4QJqga');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('94dc6d67-a57b-4dea-9509-e5ae7a097d80', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Join Artist', 'Create table orders (id INT PRIMARY KEY AUTO_INCREMENT, product_id INT, quantity INT, FOREIGN KEY (product_id) REFERENCES products(id)). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id | wc -l. How many result rows (minus header)?', 100, '$2b$10$c7dLjzo633YjyHz.LydEA.zZ.3NVrJCFeZVECbuoqHzmrXxnkPg.a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('187f1e9e-2f41-49e5-aa5e-82123be94dab', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total inventory value?', 100, '$2b$10$GGd2WP0C4y0dT9cmfM0/IucOsWL.TxEFO5KafiSPCbxEEdi3TgLFG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('18e5f9cf-4570-4a7b-934c-ed3645af7710', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Transaction Tester', 'Run: mysql -u root shopdb -e "START TRANSACTION; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && mysql -u root shopdb -e "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$fWoQpoQCgOws5KJ/CkFb2OUavyYrBNSveJ/Nz42lDQBWiqCD2w7C.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('1674fcd9-0d6f-43f3-9a3a-d127faf24b45', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'View Creator', 'Create view cheap_products as SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product appears?', 100, '$2b$10$l2dYgtraEwWFwMFwrA3I2uQ.AguHXITSc5hUapdOrLX4zDYzYMC0.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('36ad5935-4f0f-4979-83ca-6ee59b830f98', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Permission Auditor', 'Run: mysql -u root -e "SELECT user FROM mysql.user" | grep appuser. What user is listed?', 75, '$2b$10$asjm54NoZ5H8gXxXqYzJOuQDjvZmUbeeF12AqRxmGTk.GKNw/pWbW');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3eee3bbe-2dc7-4e29-8445-36b29b2e2821', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Schema Inspector', 'Run: mysql -u root shopdb -e "SHOW TABLES" | wc -l. How many tables exist (minus header)?', 75, '$2b$10$ocWshYMTbPEMeMsKGs4hW.fM/j0FFkag1qCjtqUwHDOFJEUzMmKQy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('52dff47f-68e7-4cff-9c72-62a736ad5c80', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Auto Increment Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$NmiLxleME4QSoP4rJzVe5egFYzNWgd.OnGDOQnRHSmcKDCAe9pmCe');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d86d8f3d-6dbb-4492-8a8b-effcd0ee1b7a', 'a8fac5e7-9113-42af-87b9-3bcd48ac27e7', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name="Mouse" && mysql -u root shopdb -e "SELECT price FROM products WHERE name=''Mouse''". What is the new price (rounded to 2 decimals)?', 100, '$2b$10$OoR/o3Bj.8wYFdQ7FUmAF.1I7tpcLdFvJJrqUakcdzPwc2kgVptt6');
